import requests
orcid_list=['0000-0001-6102-7846','0000-0002-0209-2784','0000-0002-1053-2030','0000-0002-2605-6569','0000-0003-0396-0333']

def fetch_count(orcid):
    url=f'https://pub.orcid.org/v3.0/{orcid}/works'
    headers={'Accept':'application/json'}
    r=requests.get(url, headers=headers, timeout=10)
    info={'orcid':orcid,'status':r.status_code,'headers':{}}
    # capture a few headers we might need
    for h in ['Retry-After','X-Rate-Limit-Reset','X-Rate-Limit-Remaining']:
        if h in r.headers:
            info['headers'][h]=r.headers[h]
    count=None
    if r.status_code==200:
        try:
            data=r.json()
            cnt=0
            for g in data.get('group', []):
                for s in g.get('work-summary', []):
                    pd=s.get('publication-date') or {}
                    yr=((pd.get('year') or {}).get('value'))
                    if yr and str(yr).isdigit() and int(yr)<2020:
                        cnt+=1
            count=cnt
        except Exception as e:
            info['error']=str(e)
    else:
        try:
            info['body']=r.text[:200]
        except Exception:
            pass
    info['count_pre_2020']=count
    return info

reports=[fetch_count(o) for o in orcid_list]
for rep in reports:
    print(rep)
